import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"content/packStack","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"content/packStack"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/prismarine/content/packStack/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/prismarine/content/packStack/"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/prismarine/src"}},"headers":[],"relativePath":"api/@jsprismarine/prismarine/content/packStack/index.md","filePath":"api/@jsprismarine/prismarine/content/packStack/index.md","lastUpdated":1794501532000}`),a={name:`api/@jsprismarine/prismarine/content/packStack/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../../">API reference</a> / <a href="./../../">@jsprismarine/prismarine</a> / content/packStack</p><h1 id="content-packstack" tabindex="-1">content/packStack <a class="header-anchor" href="#content-packstack" aria-label="Permalink to “content/packStack”">​</a></h1><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><h3 id="packstackrequest" tabindex="-1">PackStackRequest <a class="header-anchor" href="#packstackrequest" aria-label="Permalink to “PackStackRequest”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L37" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:37</a></p><p>What <a href="#resolvepackstack">resolvePackStack</a> was asked to assemble.</p><h4 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h4><h5 id="bedrockpacks" tabindex="-1">bedrockPacks? <a class="header-anchor" href="#bedrockpacks" aria-label="Permalink to “bedrockPacks?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>bedrockPacks?</strong>: readonly <code>string</code>[] | <code>&quot;all&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L56" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:56</a></p><p>Which packs to compose out of a BDS <code>behavior_packs</code> folder, by header UUID, or <code>&#39;all&#39;</code> for every pack the folder holds.</p><p>Defaults to the vanilla behavior pack alone. BDS ships chemistry, the editor, the server script libraries and four experimental toggles in that folder, and a world composes those only when it turns them on; a server aiming at vanilla parity turns none of them on. Education Edition content is out of scope by <a href="./../../../../_media/data-driven-vanilla.html">plan</a> section 12 decision 8, and the editor&#39;s five <code>editor:</code> entities are tools for a world author rather than content a server serves.</p><p>The packs are on disk either way, so naming one here is how a server that does want it opts in.</p><h5 id="javavanilla" tabindex="-1">javaVanilla? <a class="header-anchor" href="#javavanilla" aria-label="Permalink to “javaVanilla?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>javaVanilla?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L60" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:60</a></p><p>Whether to include the Java vanilla datapack. Defaults to true.</p><h5 id="overlay" tabindex="-1">overlay? <a class="header-anchor" href="#overlay" aria-label="Permalink to “overlay?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>overlay?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L58" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:58</a></p><p>Whether to include this project&#39;s block and entity vanilla overlays. Defaults to true.</p><h5 id="pluginpacks" tabindex="-1">pluginPacks? <a class="header-anchor" href="#pluginpacks" aria-label="Permalink to “pluginPacks?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>pluginPacks?</strong>: readonly <a href="./../../../packs/#packsource"><code>PackSource</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L64" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:64</a></p><p>Plugin packs, applied last so a plugin overrides a world.</p><h5 id="vanilla" tabindex="-1">vanilla? <a class="header-anchor" href="#vanilla" aria-label="Permalink to “vanilla?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>vanilla?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L39" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:39</a></p><p>Whether to include the composed vanilla Bedrock pack. Defaults to true.</p><h5 id="worldpacks" tabindex="-1">worldPacks? <a class="header-anchor" href="#worldpacks" aria-label="Permalink to “worldPacks?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>worldPacks?</strong>: readonly <a href="./../../../packs/#packsource"><code>PackSource</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L62" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:62</a></p><p>The world&#39;s own behavior packs and datapacks, applied after the vanilla members.</p><hr><h3 id="resolvedpackstack" tabindex="-1">ResolvedPackStack <a class="header-anchor" href="#resolvedpackstack" aria-label="Permalink to “ResolvedPackStack”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L68" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:68</a></p><p>The stack, plus a report of the members that could not be found.</p><h4 id="properties-1" tabindex="-1">Properties <a class="header-anchor" href="#properties-1" aria-label="Permalink to “Properties”">​</a></h4><h5 id="cache" tabindex="-1">cache? <a class="header-anchor" href="#cache" aria-label="Permalink to “cache?”">​</a></h5><blockquote><p><code>readonly</code> <code>optional</code> <strong>cache?</strong>: <a href="./../../../packs/#prefixcacheoptions"><code>PrefixCacheOptions</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L72" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:72</a></p><p>The immutable vanilla prefix cache used by the default content loader, when available.</p><h5 id="diagnostics" tabindex="-1">diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to “diagnostics”">​</a></h5><blockquote><p><code>readonly</code> <strong>diagnostics</strong>: readonly <a href="./../../../content/#diagnostic"><code>Diagnostic</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L70" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:70</a></p><h5 id="stack" tabindex="-1">stack <a class="header-anchor" href="#stack" aria-label="Permalink to “stack”">​</a></h5><blockquote><p><code>readonly</code> <strong>stack</strong>: <a href="./../../../packs/#packstack"><code>PackStack</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L69" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:69</a></p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><h3 id="pack-stack-env" tabindex="-1">PACK_STACK_ENV <a class="header-anchor" href="#pack-stack-env" aria-label="Permalink to “PACK_STACK_ENV”">​</a></h3><blockquote><p><code>const</code> <strong>PACK_STACK_ENV</strong>: <code>object</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L29" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:29</a></p><p>Points the resolver at a local copy of one fetched source.</p><h4 id="type-declaration" tabindex="-1">Type Declaration <a class="header-anchor" href="#type-declaration" aria-label="Permalink to “Type Declaration”">​</a></h4><h5 id="vanillabedrockpack" tabindex="-1">vanillaBedrockPack <a class="header-anchor" href="#vanillabedrockpack" aria-label="Permalink to “vanillaBedrockPack”">​</a></h5><blockquote><p><code>readonly</code> <strong>vanillaBedrockPack</strong>: <code>&quot;JSP_VANILLA_BEHAVIOR_PACK&quot;</code> = <code>&#39;JSP_VANILLA_BEHAVIOR_PACK&#39;</code></p></blockquote><p>A composed vanilla Bedrock behavior pack directory, or a folder of BDS vanilla layers.</p><h5 id="vanilladatapack" tabindex="-1">vanillaDatapack <a class="header-anchor" href="#vanilladatapack" aria-label="Permalink to “vanillaDatapack”">​</a></h5><blockquote><p><code>readonly</code> <strong>vanillaDatapack</strong>: <code>&quot;JSP_VANILLA_DATAPACK&quot;</code> = <code>&#39;JSP_VANILLA_DATAPACK&#39;</code></p></blockquote><p>A Java vanilla datapack directory, as the Java data generator writes one.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><h3 id="entityoverlaypackpath" tabindex="-1">entityOverlayPackPath() <a class="header-anchor" href="#entityoverlaypackpath" aria-label="Permalink to “entityOverlayPackPath()”">​</a></h3><blockquote><p><strong>entityOverlayPackPath</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L216" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:216</a></p><p>The <code>@jsprismarine/entities</code> overlay, which declares entity types absent from Bedrock&#39;s pack.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="fingerprintpackdirectories" tabindex="-1">fingerprintPackDirectories() <a class="header-anchor" href="#fingerprintpackdirectories" aria-label="Permalink to “fingerprintPackDirectories()”">​</a></h3><blockquote><p><strong>fingerprintPackDirectories</strong>(<code>directories</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L111" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:111</a></p><p>Hashes overlay paths and bytes so edits at an unchanged checkout path invalidate the cache.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="directories" tabindex="-1">directories <a class="header-anchor" href="#directories" aria-label="Permalink to “directories”">​</a></h5><p>readonly <code>string</code>[]</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="overlaypackpath" tabindex="-1">overlayPackPath() <a class="header-anchor" href="#overlaypackpath" aria-label="Permalink to “overlayPackPath()”">​</a></h3><blockquote><p><strong>overlayPackPath</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L208" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:208</a></p><p>The <code>jsprismarine_vanilla</code> overlay, which <code>@jsprismarine/blocks</code> publishes beside its <code>dist</code>.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="resolvepackstack" tabindex="-1">resolvePackStack() <a class="header-anchor" href="#resolvepackstack" aria-label="Permalink to “resolvePackStack()”">​</a></h3><blockquote><p><strong>resolvePackStack</strong>(<code>request?</code>): <a href="#resolvedpackstack"><code>ResolvedPackStack</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/14bfafb21851112e4ace597de1612b8f504916de/packages/prismarine/src/content/packStack.ts#L232" target="_blank" rel="noreferrer">prismarine/src/content/packStack.ts:232</a></p><p>Assembles the default pack stack.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="request" tabindex="-1">request? <a class="header-anchor" href="#request" aria-label="Permalink to “request?”">​</a></h5><p><a href="#packstackrequest"><code>PackStackRequest</code></a> = <code>{}</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><a href="#resolvedpackstack"><code>ResolvedPackStack</code></a></p><p>The stack in apply order, and one <code>pack.missing</code> warning per member whose directory is not on disk.</p>`,95)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};